    fill_rect(c, x1, y1, x2, y2, vmap_style_bg565());

    style = vmap_style_current();
    uint16_t extent = vmap_tile_extent(tile);
    const uint16_t forest = RGB565(style->forest_r, style->forest_g,
        style->forest_b);
