static void draw_road_layer(vmap_canvas_t * c, const vmap_tile_t * tile,
    uint16_t extent, float base_x, float base_y, float scale,
    vmap_point_t * scratch, int scratch_cap)
{
    const vmap_style_t * style = vmap_style_current();
    float u = 256.0f * scale / (float)extent;
    int cls;
    const uint16_t case_color = RGB565(style->road_case_r, style->road_case_g,
        style->road_case_b);

    if (s_road_refs && s_road_ref_cap > 0) {
        /* 一次扫描：装本瓦片 ROAD 层的要素记录起点。*/
        vmap_feature_iter_t scan = vmap_tile_layer_iter(tile, VMAP_LAYER_ROAD);
        const uint8_t * layer_end = scan.end;
        int n = 0;
        bool overflow = false;

        while (n < s_road_ref_cap) {
            const uint8_t * rec = scan.ptr;
            vmap_feature_t f;

            if (!vmap_feature_iter_next(&scan, &f)) {
                break;
            }
            s_road_refs[n++].rec = rec;
        }
        if (n == s_road_ref_cap && scan.remaining > 0) {
            overflow = true;
        }

        if (!overflow) {
            /* casing：class 顺序与原来一致（PATH → MOTORWAY）。*/
            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
                int i;

                for (i = 0; i < n; i++) {
                    const uint8_t * rec = s_road_refs[i].rec;
                    vmap_feature_iter_t one = { rec, layer_end, 1 };
                    vmap_feature_t f;
                    int raw;
                    const vmap_style_road_t * st;
                    int32_t case_w;

                    raw = rec[0];
                    if (raw < 1 || raw >= ROAD_STYLE_NUM) {
                        raw = VMAP_ROAD_RESIDENTIAL;
                    }
                    if (raw != cls) {
                        continue;
                    }
                    if (!vmap_feature_iter_next(&one, &f)) {
                        continue;
                    }
                    if (f.point_count < 2 || vmap_feature_is_closed(&f)) {
                        continue;
                    }
                    st = road_style_for(raw);
                    case_w = (int32_t)st->w + (int32_t)style->road_case_extra;
                    if (case_w > (int32_t)st->w) {
                        draw_road_feature_line(c, &f, base_x, base_y, u, case_w,
                            case_color, scratch, scratch_cap);
                    }
                }
            }

            /* fill：同上。*/
            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
                int i;

                for (i = 0; i < n; i++) {
                    const uint8_t * rec = s_road_refs[i].rec;
                    vmap_feature_iter_t one = { rec, layer_end, 1 };
                    vmap_feature_t f;
                    int raw;
                    const vmap_style_road_t * st;
                    uint16_t color;

                    raw = rec[0];
                    if (raw < 1 || raw >= ROAD_STYLE_NUM) {
                        raw = VMAP_ROAD_RESIDENTIAL;
                    }
                    if (raw != cls) {
                        continue;
                    }
                    if (!vmap_feature_iter_next(&one, &f)) {
                        continue;
                    }
                    if (f.point_count < 2 || vmap_feature_is_closed(&f)) {
                        continue;
                    }
                    st = road_style_for(raw);
                    color = RGB565(st->r, st->g, st->b);
                    draw_road_feature_line(c, &f, base_x, base_y, u,
                        (int32_t)st->w, color, scratch, scratch_cap);
                }
            }
            return;
        }
    }

    /* 回退：未绑定索引、cap<=0 或索引溢出时走原实现（逐 class 全层扫描）。*/
