static void blit_clip(const vmap_blit_surface_t * s, int32_t * x, int32_t * y,
    int32_t * w, int32_t * h)
{
    if (*x < 0) { *w += *x; *x = 0; }
    if (*y < 0) { *h += *y; *y = 0; }
    if (*x + *w > s->w) { *w = s->w - *x; }
    if (*y + *h > s->h) { *h = s->h - *y; }
    if (*w < 0) { *w = 0; }
    if (*h < 0) { *h = 0; }
}

bool vmap_blit_fill(vmap_blit_t * b, const vmap_blit_surface_t * dst,
    int32_t x, int32_t y, int32_t w, int32_t h, uint16_t color)
