/* ---- VTIL 记录序列化 ---- */
static uint8_t g_data[1 << 20];
static size_t g_len;
static uint16_t g_count;

static void put_u8(uint8_t v) { g_data[g_len++] = v; }
static void put_u16(uint16_t v) { g_data[g_len++] = (uint8_t)(v & 0xFF); g_data[g_len++] = (uint8_t)(v >> 8); }

static void add_feature(uint8_t attr, uint8_t flags, uint16_t npts,
    const uint8_t * name, uint8_t name_len)
{
    put_u8(attr);
    put_u8(flags);
    put_u16(npts);
    for (uint16_t i = 0; i < npts; i++) {
        put_u16((uint16_t)((i * 977u + attr * 131u) % 4090u));
        put_u16((uint16_t)((i * 613u + attr * 271u) % 4090u));
    }
    if (flags & VMAP_FLAG_NAMED) {
        put_u8(name_len);
        for (uint8_t i = 0; i < name_len; i++) { put_u8(name ? name[i] : (uint8_t)('a' + i)); }
    }
    g_count++;
}

static uint32_t g_rng;
static uint32_t rnd(void) { g_rng = g_rng * 1664525u + 1013904223u; return g_rng >> 8; }

