static uint16_t g_canvas_b[CANVAS_W * CANVAS_H];
static vmap_point_t g_scratch[VMAP_SCRATCH_CAP];
static vmap_road_ref_t g_refs[VMAP_ROAD_INDEX_CAP];

static int render_and_compare(const vmap_tile_t * tile, int cap, const char * tag)
{
    vmap_canvas_t c;
    int fail;

    /* A: 原路径（未绑定）。 */
    memset(g_canvas_a, 0x5A, sizeof(g_canvas_a));
    memset(&c, 0, sizeof(c));
    c.buf = g_canvas_a; c.w = CANVAS_W; c.h = CANVAS_H; c.stride = CANVAS_W * 2;
    vmap_render_bind_road_index(NULL, 0);
    vmap_render_draw_tile(&c, tile, 8.0f, 6.0f, 1.0f, g_scratch, VMAP_SCRATCH_CAP);

    /* B: 索引路径（cap 为传入值）。 */
    memset(g_canvas_b, 0x5A, sizeof(g_canvas_b));
    memset(&c, 0, sizeof(c));
    c.buf = g_canvas_b; c.w = CANVAS_W; c.h = CANVAS_H; c.stride = CANVAS_W * 2;
    vmap_render_bind_road_index(g_refs, cap);
    vmap_render_draw_tile(&c, tile, 8.0f, 6.0f, 1.0f, g_scratch, VMAP_SCRATCH_CAP);
    vmap_render_bind_road_index(NULL, 0);

    fail = memcmp(g_canvas_a, g_canvas_b, sizeof(g_canvas_a)) != 0;
    printf("%-46s cap=%-5d %s\n", tag, cap, fail ? "MISMATCH" : "ok");
    if (fail) {
        for (int i = 0; i < CANVAS_W * CANVAS_H; i++) {
            if (g_canvas_a[i] != g_canvas_b[i]) {
                printf("  first diff at (%d,%d): %04x vs %04x\n", i % CANVAS_W,
